def configure_generation_config(
    config: GenerationConfig, tokenizer: TokenizerType, is_eval=False
) -> GenerationConfig:
    """Apply specific configurations to generation config."""
    # tokenizer setting
    if "_pad_token_id" in config:
        warnings.warn(
            "'_pad_token_id' found in generation config and will be overridden with tokenizer.pad_token_id. "
            "Note: '_pad_token_id' is intended for internal use and has no effect when set in user-provided configs.",
            UserWarning,
        )
    config["_pad_token_id"] = tokenizer.pad_token_id
    if config["stop_token_ids"] is None:
        config["stop_token_ids"] = [tokenizer.eos_token_id]

    # vllm setting
    if config["backend"] == "vllm":
        config = cast(VllmConfig, config)
        # set load_format
        config["vllm_cfg"]["load_format"] = "auto" if is_eval else "dummy"

        # Respect the skip_tokenizer_init setting from the config. VLMs for example, require this to be False.
        if "skip_tokenizer_init" not in config["vllm_cfg"]:
            # set skip_tokenizer_init
            if (
                is_eval
                or config["stop_strings"] is not None
                or config["vllm_cfg"].get("expose_http_server", None)
            ):
                config["vllm_cfg"]["skip_tokenizer_init"] = False
            else:
                config["vllm_cfg"]["skip_tokenizer_init"] = True

    return config

class MeshContext:
    """Runtime distributed topology context.

    Parallelism sizes (``tp_size``, ``pp_size``, etc.) are **not** stored as
    fields; they are ``@property`` accessors that read directly from the
    attached ``DeviceMesh`` / ``moe_mesh``.  When no mesh is present the
    properties return safe defaults (``1`` for sizes, ``None`` for dp / hsdp).

    All ``DeviceMesh`` objects passed in must use axis names from
    :class:`MeshAxisName`; a ``ValueError`` is raised on construction if
    any unknown name is encountered.

    Lifecycle
    ---------
    1. Recipes parse YAML to obtain sizes and strategy configs.
    2. Sizes are passed to :meth:`build` to build ``DeviceMesh``
       objects.
    3. ``MeshContext`` is created with those meshes; axis names are
       validated automatically in ``__post_init__``.

    Alternatively, :meth:`from_meshes` constructs an instance directly from
    ``DeviceMesh`` objects (used by ``NeMoAutoModel.from_pretrained``).

    Attributes:
        device_mesh: Device mesh for distributed training.
        moe_mesh: MoE-specific device mesh.
        process_group: Optional model-local group for recipe-level collectives
            that must not involve ranks outside this mesh.
    """

